)), body: ListView(padding: const EdgeInsets.all(20), children: [step == 0 ? SurfaceCard(child: Text(widget.tenant.data['fullName'] as String? ?? 'Tenant')) : step == 1 ? DropdownButtonFormField<String>(value: propertyId, items: (properties.data ?? []).where((item) => item.data['status'] == 'active').map((item) => DropdownMenuItem(value: item.id, child: Text(item.data['name'] as String? ?? 'Property'))).toList(), onChanged: (value) => setState(() { propertyId = value; unitId = null; }), decoration: const InputDecoration(labelText: 'Select Property')) : step == 2 ? Column(children: available.map((item) => RadioListTile<String>(value: item.id, groupValue: unitId, onChanged: (value) => setState(() { unitId = value; rent.text = (((item.data['monthlyRentPaise'] as num?)?.toDouble() ?? 0) / 100).toStringAsFixed(0); deposit.text = (((item.data['expectedSecurityDepositPaise'] as num?)?.toDouble() ?? 0) / 100).toStringAsFixed(0); }), title: Text(item.data['name'] as String? ?? 'Unit'), subtitle: Text('${item.data['type']} · ${formatInr((item.data['monthlyRentPaise'] as num?)?.toInt())} · Vacant'))).toList()) : step == 3 ? Column(children: [_field(start, 'Start date'), _field(end, 'End date (optional)'), _field(rent, 'Monthly rent (₹)'), _field(deposit, 'Security deposit agreed (₹)'), _field(due, 'Rent due day (1–28)'), _field(notice, 'Notice period days'), _field(notes, 'Notes')]) : SurfaceCard(child: Text('${widget.tenant.data['fullName']}\nStart: ${start.text}\nMonthly Rent: ₹${rent.text}\nDeposit Agreed: ₹${deposit.text}\nDue Day: ${due.text}')), const SizedBox(height: 24), Row(children: [if (step > 0) Expanded(child: CreovyButton(label: 'Back', variant: CreovyButtonVariant.outline, onPressed: () => setState(() => step--))), if (step > 0) const SizedBox(width: 10), Expanded(child: CreovyButton(label: step == 4 ? 'Create Agreement' : 'Continue', loading: busy, onPressed: step == 4 ? save : () => setState(() => step++)))])]); })); Widget _field(TextEditingController controller, String label) => Padding(padding: const EdgeInsets.only(bottom: 12), child: TextField(controller: controller, decoration: InputDecoration(labelText: label))); }

class AgreementDetailScreen extends StatelessWidget { const AgreementDetailScreen({super.key, required this.account, required this.agreement}); final AccountContext account; final AgreementRecord agreement; @override Widget build(BuildContext context) { final data = agreement.data; final status = data['status'] as String? ?? 'draft'; return Scaffold(appBar: AppBar(title: const Text('Rental Agreement')), body: ListView(padding: const EdgeInsets.all(20), children: [StatusChip(label: _status(status)), const SizedBox(height: 16), SurfaceCard(child: Text('Monthly Rent: ${formatInr((data['monthlyRentPaise'] as num?)?.toInt())}\nSecurity Deposit Agreed: ${formatInr((data['securityDepositAgreedPaise'] as num?)?.toInt())}\nStart: ${data['startDate']}\nEnd: ${data['endDate'] ?? 'Open ended'}\nDue Day: ${data['rentDueDay']}\nNotice: ${data['noticePeriodDays'] ?? 0} days\n${data['notes'] ?? ''}')), const SizedBox(height: 24), if (status == 'draft' || status == 'upcoming') CreovyButton(label: 'Activate Agreement', icon: Icons.play_arrow, onPressed: () async { final okay = await showCreovyConfirmation(context, title: 'Activate rental agreement?', body: 'This will mark the selected unit as occupied by this tenant.', confirmLabel: 'Activate'); if (okay) { try { await TenantRepository(FirebaseFirestore.instance).activateAgreement(agreement); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Agreement activated successfully.'))); } catch (e) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(e.toString()))); } } }), if (status == 'active') CreovyButton(label: 'End Agreement', icon: Icons.stop_circle_outlined, onPressed: () async { final okay = await showCreovyConfirmation(context, title: 'End this rental agreement?', body: 'The unit will become vacant. Financial and security-deposit settlement will be handled separately.', confirmLabel: 'End Agreement'); if (okay) await TenantRepository(FirebaseFirestore.instance).endAgreement(agreement, 'ended'); })])); } }
